// Which API list each tool reads. Only what the agent filled in goes into the query.
const MAX_PAGE_SIZE = 100;
const MY_LIST_SIZE = 20;
const LOCAL_TIME = /^([01]\d|2[0-4]):[0-5]\d$/;
const input = $json;
const optional = (value) => String(value ?? '').trim();

if (input.tool === 'find_free_times') {
  const query = { date: optional(input.date), free: true, size: MAX_PAGE_SIZE };
  if (Number(input.venueId) > 0) query.venueId = Number(input.venueId);
  if (optional(input.type)) query.type = optional(input.type);
  if (LOCAL_TIME.test(optional(input.from))) query.from = optional(input.from);
  if (LOCAL_TIME.test(optional(input.to))) query.to = optional(input.to);
  return { json: { path: 'availability', query } };
}
if (input.tool === 'my_bookings') {
  return { json: { path: 'bookings', query: { from: new Date().toISOString(), size: MY_LIST_SIZE, sort: 'startsAt,asc' } } };
}
if (input.tool === 'my_memberships') {
  return { json: { path: 'memberships', query: { size: MY_LIST_SIZE, sort: 'startsOn,desc' } } };
}
throw new Error('Unknown tool: ' + input.tool);

// What the agent reads: Sri Lankan times and "LKR 2,500", never UTC or cents.
const call = $('Tool Call').item.json;
const names = JSON.parse(call.names);
const DEFAULT_TIME_ZONE = 'Asia/Colombo';
const BOOKING_WORDS = {
  AWAITING_PAYMENT: 'waiting for payment',
  AWAITING_CHECK: 'receipt sent, the venue is checking it',
  CONFIRMED: 'confirmed',
  EXPIRED: 'expired, as it was not paid in time',
  CANCELLED: 'cancelled',
};
const MEMBERSHIP_WORDS = { ...BOOKING_WORDS, ACTIVE: 'active', ENDED: 'ended' };

const money = (m) => m.currency + ' ' + (m.amount / 100).toLocaleString('en-US', { maximumFractionDigits: 2 });
const zoneOf = (venueId) => names.venues[venueId]?.timeZone ?? DEFAULT_TIME_ZONE;
const time = (iso, timeZone) => new Date(iso).toLocaleTimeString('en-GB', { timeZone, hour: 'numeric', minute: '2-digit', hour12: true });
const day = (iso, timeZone) => new Date(iso).toLocaleDateString('en-GB', { timeZone, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
const localDay = (isoDate) => day(isoDate + 'T12:00:00Z', 'UTC');
const venueName = (venueId) => names.venues[venueId]?.name ?? 'a venue that is closed for now';
const resourceName = (resourceId) => {
  const resource = names.resources[resourceId];
  return resource ? resource.name + ' at ' + venueName(resource.venueId) : 'a resource no longer listed';
};
const toPay = (item) =>
  item.status === 'AWAITING_PAYMENT' && item.expiresAt
    ? ': send ' + money(item.amountDue) + ' by ' + time(item.expiresAt, zoneOf(item.venueId)) + ' on ' + day(item.expiresAt, zoneOf(item.venueId))
    : item.balance.amount > 0 && (item.status === 'CONFIRMED' || item.status === 'ACTIVE')
      ? ', ' + money(item.balance) + ' still to pay at the venue'
      : '';

function answer() {
  if ($json.error || !$json.body) return 'The check failed. Tell the customer you can\'t check right now.';
  const { statusCode, body } = $json;
  if (statusCode >= 400) {
    const why = (body.errors ?? []).map((e) => e.field + ': ' + e.message).join('; ') || body.message;
    return 'The check was refused (' + why + ').' + (statusCode >= 500 ? " Tell the customer you can't check right now." : '');
  }
  const { content, totalElements } = body.data;

  if (call.tool === 'find_free_times') {
    const date = localDay(call.date);
    if (content.length === 0) return 'Nothing is free on ' + date + ' for this search.';
    const byResource = new Map();
    for (const slot of content) byResource.set(slot.resourceId, [...(byResource.get(slot.resourceId) ?? []), slot]);
    const lines = ['Free start times on ' + date + ' (each price is for one slot from that time):'];
    for (const [resourceId, slots] of byResource) {
      const resource = names.resources[resourceId];
      lines.push(resourceName(resourceId) + (resource ? ', ' + resource.slotMinutes + '-minute slots:' : ':'));
      const byPrice = new Map();
      for (const slot of slots) {
        const price = money(slot.price);
        byPrice.set(price, [...(byPrice.get(price) ?? []), time(slot.startsAt, zoneOf(resource?.venueId))]);
      }
      for (const [price, times] of byPrice) lines.push('• ' + price + ': ' + times.join(', '));
    }
    if (totalElements > content.length) {
      lines.push('Only the first ' + content.length + ' of ' + totalElements + ' free start times are listed. Ask about a narrower time or one venue for the rest.');
    }
    return lines.join('\n');
  }

  if (call.tool === 'my_bookings') {
    if (content.length === 0) return 'The customer has no upcoming bookings.';
    const lines = content.map((b) => {
      const zone = zoneOf(b.venueId);
      return '• ' + resourceName(b.resourceId) + ', ' + day(b.startsAt, zone) + ', ' + time(b.startsAt, zone) + ' to ' + time(b.endsAt, zone) +
        ', ' + money(b.price) + ': ' + BOOKING_WORDS[b.status] + toPay(b);
    });
    return ['The customer\'s upcoming bookings:', ...lines].join('\n');
  }

  if (content.length === 0) return 'The customer has no memberships.';
  const lines = content.map((m) =>
    '• ' + m.planName + ' at ' + venueName(m.venueId) + ', ' + localDay(m.startsOn) + ' to ' + localDay(m.endsOn) +
      ', ' + money(m.price) + ': ' + MEMBERSHIP_WORDS[m.status] + toPay(m));
  return ['The customer\'s memberships, newest first:', ...lines].join('\n');
}

return { json: { result: answer() } };
